/* @autogenerated */
import { Subject } from 'rxjs';
import { QueryList, TemplateRef } from '@angular/core';
import { LocalRouteContextComponent } from './local-route-context.component';
import { LocalRouteDirective } from './local-route.directive';
import { LocalRouteStateService } from '@shared/interaction/local-route-state/local-route-state.service';

describe('LocalRouteContextComponent', () => {
  it('selects initial, matching, and fallback templates', () => {
    const routeState = {} as LocalRouteStateService;
    const component = new LocalRouteContextComponent(routeState);

    const initial = new LocalRouteDirective({} as TemplateRef<unknown>);
    initial.initial = true;

    const match = new LocalRouteDirective({} as TemplateRef<unknown>);
    match.on = 'detail';

    const fallback = new LocalRouteDirective({} as TemplateRef<unknown>);
    fallback.fallback = true;

    const list = new QueryList<LocalRouteDirective>();
    list.reset([initial, match, fallback]);
    component.templates = list;

    component.setTemplateForParam('detail');
    expect(component.currentTemplate).toBe(match.template);

    component.setTemplateForParam('missing');
    expect(component.currentTemplate).toBe(fallback.template);

    component.setTemplateForParam(undefined);
    expect(component.currentTemplate).toBe(initial.template);
  });

  it('binds its param when it has none and follows it in the url', () => {
    const params = new Subject<Record<string, string>>();
    const bind = { watch: () => params } as any;
    const routeState = { bind: jasmine.createSpy('bind').and.returnValue(bind) } as unknown as LocalRouteStateService;
    const component = new LocalRouteContextComponent(routeState);
    component.param = '';
    const detail = new LocalRouteDirective({} as TemplateRef<unknown>);
    detail.on = 'detail';
    const list = new QueryList<LocalRouteDirective>();
    list.reset([detail]);
    component.templates = list;

    component.ngOnChanges({});
    component.ngAfterContentInit();
    params.next({ view: 'detail' });

    expect(routeState.bind).toHaveBeenCalledOnceWith(['view']);
    expect(component.currentTemplate).toBe(detail.template);

    component.ngOnDestroy();
    params.next({ view: 'other' });
    expect(component.currentTemplate).toBe(detail.template);
  });

  it('has no template without templates', () => {
    const component = new LocalRouteContextComponent({} as LocalRouteStateService);

    component.setTemplateForParam('detail');

    expect(component.currentTemplate).toBeNull();
  });
});
